// The Moran scatter plot: every tract's standardised share (x) against the
// mean of its neighbours' (y, the spatial lag). The slope of the line through
// the origin is Moran's I; the four quadrants are the four kinds of local
// association, coloured as on the cluster map when the tract is significant.
//
// Drag a rectangle (or draw a lasso from the toolbox) to select tracts: their
// geoids go to the multi-value variable SEL, and both maps ring them. Clicking
// a point selects that one tract, clicking it again clears; a click on a map
// selects there too, and the point grows here. The trash icon clears.
//
// A dashboard changes only the constants block below.
// @constants begin
const SEL = 'sel';
const COLORS = {
  'High-High': '#d7301f',
  'Low-Low': '#2166ac',
  'High-Low': '#f4a582',
  'Low-High': '#92c5de',
  'Not significant': 'rgba(128, 128, 128, 0.35)',
  'No neighbours': 'rgba(128, 128, 128, 0.35)',
};
const UNIT = '% of residents';
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;

const frame = context.panel.data.series.find((f) => f.refId === 'A');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const geoid = col('geoid');
const name = col('name');
const county = col('county');
const share = col('share').map(Number);
const z = col('z').map(Number);
const lag = col('lag').map((v) => (v === null || v === undefined ? null : Number(v)));
const p = col('p').map((v) => (v === null || v === undefined ? null : Number(v)));
const cluster = col('cluster');

// The selection, read on every draw so a shared link shows it too. Naming
// ${sel} here is what makes the panel redraw when the variable changes.
let picked = [];
try {
  picked = JSON.parse(context.grafana.replaceVariables('${sel:json}'));
} catch (e) {
  picked = [];
}
// Only what this state has: a selection made in another state matches nothing.
const here = new Set(geoid);
const selected = new Set((Array.isArray(picked) ? picked : [picked]).filter((v) => v && here.has(v)));
const anySelected = selected.size > 0;
// A handful of points must stand out among thousands; hundreds must not hide the rest.
const pickedSize = selected.size <= 5 ? 14 : 9;

// Moran's I as GeoDa draws it: the slope of lag on z, over tracts with
// neighbours (z has mean 0 and variance 1 over all of them).
let szl = 0;
let withNeighbours = 0;
for (let i = 0; i < z.length; i++) {
  if (lag[i] !== null) {
    szl += z[i] * lag[i];
    withNeighbours += 1;
  }
}
const moran = withNeighbours ? szl / withNeighbours : 0;
const xs = z.filter(Number.isFinite);
const xMin = Math.min(-1, ...xs);
const xMax = Math.max(1, ...xs);

const point = (i) => ({
  value: [z[i], lag[i], i],
  itemStyle: {
    color: COLORS[cluster[i]] || COLORS['Not significant'],
    opacity: anySelected && !selected.has(geoid[i]) ? 0.15 : 0.9,
    borderColor: selected.has(geoid[i]) ? theme.colors.text.primary : 'transparent',
    borderWidth: selected.has(geoid[i]) ? 2 : 0,
  },
  symbolSize: selected.has(geoid[i]) ? pickedSize : 5,
});
const rest = [];
const front = [];
for (let i = 0; i < z.length; i++) {
  if (lag[i] === null || !Number.isFinite(z[i])) {
    continue;
  }
  const significant = cluster[i] !== 'Not significant';
  (selected.has(geoid[i]) || (!anySelected && significant) ? front : rest).push(point(i));
}

const publish = (ids) => location.partial({ ['var-' + SEL]: ids.length ? ids : '' }, true);

// Points inside a brushed area. A rectangle comes as [[x0, x1], [y0, y1]],
// a lasso as its vertices.
const inside = (area, x, y) => {
  if (area.brushType === 'rect') {
    const [[x0, x1], [y0, y1]] = area.coordRange;
    return x >= x0 && x <= x1 && y >= y0 && y <= y1;
  }
  const poly = area.coordRange;
  let hit = false;
  for (let a = 0, b = poly.length - 1; a < poly.length; b = a++) {
    const [xa, ya] = poly[a];
    const [xb, yb] = poly[b];
    if (ya > y !== yb > y && x < ((xb - xa) * (y - ya)) / (yb - ya) + xa) {
      hit = !hit;
    }
  }
  return hit;
};

chart.off('brushEnd');
chart.on('brushEnd', (event) => {
  const areas = (event.areas || []).filter((a) => a.coordRange);
  if (!areas.length) {
    return;
  }
  const ids = [];
  for (let i = 0; i < z.length; i++) {
    if (lag[i] !== null && areas.some((a) => inside(a, z[i], lag[i]))) {
      ids.push(geoid[i]);
    }
  }
  publish(ids);
  // The highlighted points now show the selection; the box would only hide them.
  setTimeout(() => chart.dispatchAction({ type: 'brush', areas: [] }), 0);
});
chart.off('brush');
chart.on('brush', (event) => {
  if (event.command === 'clear') {
    publish([]);
  }
});
chart.off('click');
chart.on('click', (event) => {
  const i = event.value && event.value[2];
  if (i === undefined) {
    return;
  }
  const same = selected.size === 1 && selected.has(geoid[i]);
  publish(same ? [] : [geoid[i]]);
});
setTimeout(() => {
  chart.dispatchAction({ type: 'takeGlobalCursor', key: 'brush', brushOption: { brushType: 'rect', brushMode: 'single' } });
}, 0);

const fmt = (v, d) => (v === null || v === undefined || !Number.isFinite(v) ? '–' : v.toFixed(d));
const series = (data, extra) => ({
  type: 'scatter',
  data,
  emphasis: { scale: 1.6 },
  ...extra,
});

return {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 12, right: 24, top: 36, bottom: 30, containLabel: true },
  tooltip: {
    trigger: 'item',
    formatter: (item) => {
      if (item.seriesName === 'line') {
        return `Moran's I = <b>${moran.toFixed(3)}</b>`;
      }
      const i = item.value[2];
      return (
        `<b>${name[i]}</b>, ${county[i]}<br/>` +
        `share: <b>${fmt(share[i], 1)}</b> ${UNIT} (z ${fmt(z[i], 2)})<br/>` +
        `neighbours' mean z: <b>${fmt(lag[i], 2)}</b><br/>` +
        `${cluster[i]} · pseudo p = ${fmt(p[i], 3)}`
      );
    },
  },
  toolbox: {
    right: 8,
    top: 0,
    itemSize: 14,
    feature: {
      brush: {
        type: ['rect', 'polygon', 'clear'],
        title: { rect: 'Select tracts in a box', polygon: 'Select tracts with a lasso', clear: 'Clear the selection' },
      },
    },
  },
  brush: {
    xAxisIndex: 0,
    yAxisIndex: 0,
    brushType: 'rect',
    brushMode: 'single',
    transformable: false,
    brushStyle: { color: 'rgba(128, 128, 128, 0.12)', borderColor: muted, borderWidth: 1 },
    inBrush: {},
    outOfBrush: {},
  },
  title: {
    text: `Moran's I = ${moran.toFixed(3)}` + (anySelected ? `   ·   ${selected.size} selected` : ''),
    left: 8,
    top: 4,
    textStyle: { fontSize: 13, fontWeight: 'normal', color: theme.colors.text.primary },
  },
  xAxis: {
    type: 'value',
    name: `share, standardised (z of ${UNIT})`,
    nameLocation: 'middle',
    nameGap: 26,
    nameTextStyle: { color: muted },
    axisLabel: { color: muted },
    splitLine: { show: false },
    axisLine: { onZero: false },
  },
  yAxis: {
    type: 'value',
    name: "neighbours' mean z (spatial lag)",
    nameLocation: 'middle',
    nameGap: 36,
    nameTextStyle: { color: muted },
    axisLabel: { color: muted },
    splitLine: { show: false },
    axisLine: { onZero: false },
  },
  series: [
    series(rest, { name: 'tracts', z: 1 }),
    series(front, { name: 'highlighted', z: 2 }),
    {
      name: 'line',
      type: 'line',
      data: [
        [xMin, moran * xMin],
        [xMax, moran * xMax],
      ],
      symbol: 'none',
      silent: true,
      z: 3,
      lineStyle: { color: theme.colors.text.primary, width: 1.5 },
      markLine: {
        silent: true,
        symbol: 'none',
        label: { show: false },
        lineStyle: { color: muted, type: 'dashed', width: 1, opacity: 0.6 },
        data: [{ xAxis: 0 }, { yAxis: 0 }],
      },
    },
  ],
};

